// Some portions generated by Codex
package org.eclipse.rdf4j.query.parser;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;

import org.eclipse.rdf4j.query.QueryParseOptions;
import org.junit.jupiter.api.Test;

class QueryParserOptionsCompatibilityTest {

	@Test
	void legacyParserUsesOldMethodsForDefaultAndRejectsUnsupportedPolicies() {
		LegacyParser parser = new LegacyParser();

		assertNull(parser.parseQuery("SELECT * WHERE {}", "urn:query:", QueryParseOptions.DEFAULT));
		assertEquals("SELECT * WHERE {}", parser.query);
		assertEquals("urn:query:", parser.queryBase);
		assertNull(parser.parseUpdate("INSERT DATA {}", "urn:update:", QueryParseOptions.DEFAULT));
		assertEquals("INSERT DATA {}", parser.update);
		assertEquals("urn:update:", parser.updateBase);
		assertEquals(1, parser.queryCalls);
		assertEquals(1, parser.updateCalls);

		assertThrows(UnsupportedOperationException.class,
				() -> parser.parseQuery("SELECT * WHERE {}", null, QueryParseOptions.STRICT));
		assertThrows(UnsupportedOperationException.class,
				() -> parser.parseUpdate("INSERT DATA {}", null, QueryParseOptions.STRICT));
		assertThrows(NullPointerException.class, () -> parser.parseQuery("SELECT * WHERE {}", null, null));
		assertThrows(NullPointerException.class, () -> parser.parseUpdate("INSERT DATA {}", null, null));
		assertEquals(1, parser.queryCalls, "unsupported options must not reach legacy parser methods");
		assertEquals(1, parser.updateCalls, "unsupported options must not reach legacy parser methods");
	}

	private static final class LegacyParser implements QueryParser {
		private String query;
		private String queryBase;
		private String update;
		private String updateBase;
		private int queryCalls;
		private int updateCalls;

		@Override
		public ParsedUpdate parseUpdate(String updateStr, String baseURI) {
			updateCalls++;
			update = updateStr;
			updateBase = baseURI;
			return null;
		}

		@Override
		public ParsedQuery parseQuery(String queryStr, String baseURI) {
			queryCalls++;
			query = queryStr;
			queryBase = baseURI;
			return null;
		}
	}
}
